/* ==========================================================================
   Página Home — Curso de IA "Trabalhando em Par com IA"
   Utilitários de autoria da página (complementam o Tailwind do layout).
   ========================================================================== */

/* Tipografia de seção */
.c2f-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: #6ee7b7;
}

.c2f-eyebrow::before {
    content: '';
    display: inline-block;
    width: 1.5rem;
    height: 2px;
    border-radius: 2px;
    background: linear-gradient(90deg, #10b981, #34d399);
    box-shadow: 0 0 10px rgba(52, 211, 153, 0.6);
}

.c2f-h2 {
    font-size: clamp(1.875rem, 1.2rem + 2.4vw, 3rem);
    font-weight: 900;
    line-height: 1.1;
    letter-spacing: -0.02em;
    color: #fff;
}

/* Texto com gradiente esmeralda animado */
.c2f-gradient-text {
    background: linear-gradient(90deg, #34d399, #a7f3d0, #10b981, #34d399);
    background-size: 300% 100%;
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    animation: c2f-gradient 8s ease infinite;
}

@keyframes c2f-gradient {
    0%, 100% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
}

/* Cards genéricos: brilho seguindo o mouse via variáveis */
.c2f-card {
    will-change: transform;
}

/* Status dos episódios */
.c2f-status-on,
.c2f-status-soon {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.25rem 0.65rem;
    border-radius: 9999px;
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    white-space: nowrap;
}

.c2f-status-on {
    color: #6ee7b7;
    background: rgba(16, 185, 129, 0.12);
    border: 1px solid rgba(16, 185, 129, 0.35);
    box-shadow: 0 0 14px -4px rgba(52, 211, 153, 0.6);
}

.c2f-status-on::before {
    content: '';
    width: 0.4rem;
    height: 0.4rem;
    border-radius: 9999px;
    background: #34d399;
    box-shadow: 0 0 8px #34d399;
    animation: c2f-blink 2s ease-in-out infinite;
}

.c2f-status-soon {
    color: #fcd34d;
    background: rgba(251, 191, 36, 0.1);
    border: 1px solid rgba(251, 191, 36, 0.35);
}

@keyframes c2f-blink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.35; }
}

/* Terminal do hero */
.c2f-scanlines::after {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.025) 0 1px, transparent 1px 3px);
    mix-blend-mode: overlay;
}

.c2f-cursor {
    animation: c2f-blink 1s steps(2, end) infinite;
}

.c2f-eq {
    transform-origin: bottom;
    animation: c2f-eq 1.1s ease-in-out infinite;
}

@keyframes c2f-eq {
    0%, 100% { transform: scaleY(0.4); }
    50% { transform: scaleY(1.4); }
}

/* Inclinação 3D suave do mockup */
.c2f-tilt {
    transform: perspective(1200px) rotateY(-6deg) rotateX(3deg);
    transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

.c2f-tilt:hover {
    transform: perspective(1200px) rotateY(0deg) rotateX(0deg) translateY(-4px);
}

/* Faixa de marcas (marquee infinito) */
.c2f-marquee-mask {
    mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);
    -webkit-mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);
}

.c2f-marquee {
    animation: c2f-marquee 38s linear infinite;
}

.c2f-marquee:hover {
    animation-play-state: paused;
}

@keyframes c2f-marquee {
    from { transform: translateX(0); }
    to { transform: translateX(-50%); }
}

.c2f-chip {
    display: inline-flex;
    align-items: center;
    padding: 0.5rem 1rem;
    border-radius: 9999px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(255, 255, 255, 0.03);
    font-size: 0.8rem;
    font-weight: 700;
    color: #94a3b8;
    white-space: nowrap;
    transition: all 0.3s ease;
}

.c2f-chip:hover {
    color: #a7f3d0;
    border-color: rgba(16, 185, 129, 0.4);
    background: rgba(16, 185, 129, 0.08);
}

/* Tags do repositório */
.c2f-tag {
    display: inline-flex;
    padding: 0.25rem 0.7rem;
    border-radius: 0.5rem;
    border: 1px solid rgba(16, 185, 129, 0.25);
    background: rgba(16, 185, 129, 0.08);
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
    font-size: 0.7rem;
    font-weight: 700;
    color: #6ee7b7;
}

/* Lista de materiais */
.c2f-material {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: 1.1rem 1.25rem;
    border-radius: 1rem;
    border: 1px solid rgba(255, 255, 255, 0.06);
    background: rgba(255, 255, 255, 0.025);
    transition: all 0.3s ease;
}

.c2f-material:hover {
    border-color: rgba(16, 185, 129, 0.4);
    background: rgba(16, 185, 129, 0.06);
    transform: translateX(6px);
}

.c2f-material-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.75rem;
    background: rgba(16, 185, 129, 0.12);
    color: #6ee7b7;
    transition: all 0.3s ease;
}

.c2f-material:hover .c2f-material-icon {
    background: #34d399;
    color: #060e0a;
    box-shadow: 0 0 20px rgba(52, 211, 153, 0.6);
}

.c2f-material-arrow {
    flex-shrink: 0;
    font-size: 1.25rem;
    font-weight: 900;
    color: #475569;
    transition: all 0.3s ease;
}

.c2f-material:hover .c2f-material-arrow {
    color: #34d399;
    transform: translateY(3px);
}

/* Stack */
.c2f-stack {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: 1rem;
    padding: 1.5rem;
    border-radius: 1.25rem;
    border: 1px solid rgba(255, 255, 255, 0.06);
    background: rgba(10, 21, 16, 0.7);
    transition: all 0.3s ease;
    overflow: hidden;
}

.c2f-stack::before {
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(circle at 0% 0%, rgba(16, 185, 129, 0.18), transparent 55%);
    opacity: 0;
    transition: opacity 0.4s ease;
}

.c2f-stack:hover {
    border-color: rgba(16, 185, 129, 0.45);
    transform: translateY(-4px);
    box-shadow: 0 20px 40px -20px rgba(16, 185, 129, 0.5);
}

.c2f-stack:hover::before {
    opacity: 1;
}

.c2f-stack-icon {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 3.25rem;
    height: 3.25rem;
    border-radius: 0.9rem;
    background: rgba(16, 185, 129, 0.1);
    border: 1px solid rgba(16, 185, 129, 0.25);
    color: #6ee7b7;
    transition: all 0.3s ease;
}

.c2f-stack:hover .c2f-stack-icon {
    color: #060e0a;
    background: linear-gradient(135deg, #34d399, #10b981);
    box-shadow: 0 0 24px rgba(52, 211, 153, 0.6);
    transform: rotate(-6deg) scale(1.05);
}

.c2f-stack-tag {
    position: absolute;
    top: 1.25rem;
    right: 1.25rem;
    padding: 0.2rem 0.6rem;
    border-radius: 9999px;
    font-size: 0.6rem;
    font-weight: 800;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: #94a3b8;
    border: 1px solid rgba(255, 255, 255, 0.08);
}

/* FAQ */
.c2f-faq {
    border-radius: 1rem;
    border: 1px solid rgba(255, 255, 255, 0.06);
    background: rgba(10, 21, 16, 0.6);
    transition: border-color 0.3s ease, background 0.3s ease;
}

.c2f-faq[open] {
    border-color: rgba(16, 185, 129, 0.4);
    background: rgba(16, 185, 129, 0.05);
}

.c2f-faq summary {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding: 1.25rem 1.5rem;
    cursor: pointer;
    list-style: none;
    font-size: 1.05rem;
    font-weight: 800;
    color: #fff;
}

.c2f-faq summary::-webkit-details-marker {
    display: none;
}

.c2f-faq-icon {
    position: relative;
    flex-shrink: 0;
    width: 1.75rem;
    height: 1.75rem;
    border-radius: 9999px;
    border: 1px solid rgba(16, 185, 129, 0.4);
    transition: all 0.3s ease;
}

.c2f-faq-icon::before,
.c2f-faq-icon::after {
    content: '';
    position: absolute;
    left: 50%;
    top: 50%;
    width: 0.75rem;
    height: 2px;
    border-radius: 2px;
    background: #34d399;
    transform: translate(-50%, -50%);
    transition: transform 0.3s ease;
}

.c2f-faq-icon::after {
    transform: translate(-50%, -50%) rotate(90deg);
}

.c2f-faq[open] .c2f-faq-icon {
    background: #34d399;
    box-shadow: 0 0 16px rgba(52, 211, 153, 0.6);
}

.c2f-faq[open] .c2f-faq-icon::before,
.c2f-faq[open] .c2f-faq-icon::after {
    background: #060e0a;
}

.c2f-faq[open] .c2f-faq-icon::after {
    transform: translate(-50%, -50%) rotate(0deg);
}

.c2f-faq-body {
    padding: 0 1.5rem 1.5rem;
    font-size: 0.95rem;
    line-height: 1.7;
    color: #94a3b8;
    animation: c2f-faq-in 0.35s ease;
}

@keyframes c2f-faq-in {
    from { opacity: 0; transform: translateY(-6px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Check do CTA */
.c2f-check {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.25rem;
    height: 1.25rem;
    border-radius: 9999px;
    background: rgba(16, 185, 129, 0.2);
    color: #34d399;
    font-size: 0.7rem;
    font-weight: 900;
}

@media (prefers-reduced-motion: reduce) {
    .c2f-gradient-text,
    .c2f-marquee,
    .c2f-eq,
    .c2f-cursor,
    .c2f-status-on::before {
        animation: none !important;
    }

    .c2f-tilt {
        transform: none;
    }
}
